{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "P - Population: Hospitals (Primary, Secondary, Tertiary, private, and specialty). I - Intervention: Accredited healthcare organization. C - Comparison: Not applicable. O - Outcomes: Quality, Patient safety, organizational performance. S - Study Design: Quantitative, qualitative, and mixed-method studies.",
      "reason": "Eligible study characteristics are specified using the PI(C)OS framework (population, intervention, outcomes, and study designs) and the hospital settings are described. However, follow-up requirements are not reported."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Peer-reviewed journals should be in English and published between 2014 and 2024.",
      "reason": "The eligibility criteria for report characteristics include both language (English) and dissemination/publication period (2014 to 2024)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No statement was found that distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "The narrative synthesis followed Synthesis Without Meta-Analyses (SWiM) reporting principles, (Campbell et al., BMJ 2020;368:l6890; the completed SWiM checklist is provided as Supplementary File 3), summarising direction of effect, vote-counting based on direction, and key contextual moderators (income setting, accreditation body, hospital type).",
      "reason": "Groups used for synthesis are partly specified via contextual moderators (income setting, accreditation body, hospital type). However, the evidence does not clearly specify groups “in each synthesis” and does not link them to comparisons defined in the review objectives (no review objectives/comparisons are provided in the retrieved evidence)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Studies that reported the construct only qualitatively, used non-convertible categorical outcomes, or lacked dispersion statistics were excluded from pooling and analysed narratively.",
      "reason": "The manuscript provides a rationale for a notable restriction on eligibility/synthesis (excluding certain studies from pooling and analyzing them narratively due to lack of compatible quantitative data)."
    }
  ],
  "confidence": 70
}

